<template><div class="space-y-6"><header><h1 class="text-2xl font-bold">Other Assets</h1><p class="text-sm text-gray-500">Property, vehicles, gold, collectibles, business assets, and other recorded value.</p></header><StatCard label="Recorded asset value" :value="money(total)"/><form class="grid gap-3 rounded-xl border bg-white p-5 sm:grid-cols-3" @submit.prevent="add"><select v-model="form.assetType" class="rounded-lg border-gray-300"><option v-for="t in types" :key="t">{{t}}</option></select><input v-model="form.name" required placeholder="Asset name" class="rounded-lg border-gray-300"><input v-model.number="form.purchaseValue" min="0" type="number" placeholder="Purchase value" class="rounded-lg border-gray-300"><input v-model.number="form.currentEstimatedValue" required min="0" type="number" placeholder="Current value" class="rounded-lg border-gray-300"><input v-model="form.valuationDate" required type="date" class="rounded-lg border-gray-300"><input v-model.number="form.associatedLoanId" min="1" type="number" placeholder="Associated loan ID (optional)" class="rounded-lg border-gray-300"><button class="rounded-lg bg-indigo-600 px-4 py-2 text-white">Add asset</button></form><div class="rounded-xl border bg-white p-5"><p v-if="!items.length" class="text-sm text-gray-500">No other assets recorded. Investments remain managed in Investments.</p><div v-for="x in items" :key="x.id" class="flex justify-between border-b py-3"><div><b>{{x.name}}</b><p class="text-sm text-gray-500">{{x.assetType}} · valued {{x.valuationDate}}</p></div><div class="text-right"><b>{{money(x.currentEstimatedValue)}}</b><button class="ml-3 text-sm text-red-600" @click="remove(x.id)">Delete</button></div></div></div></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{assetsApi}from'../api/assets';import{formatMoney as money}from'../utils/formatters';import StatCard from'../components/StatCard.vue';const items=ref([]),types=['Property','Vehicle','Gold','Collectible','Business','Other'],form=reactive({assetType:'Property',name:'',purchaseValue:null,currentEstimatedValue:0,valuationDate:new Date().toISOString().slice(0,10),associatedLoanId:null});const load=async()=>items.value=(await assetsApi.list()).data?.data??[],add=async()=>{await assetsApi.add({...form,associatedLoanId:form.associatedLoanId||null});form.name='';await load()},remove=async id=>{await assetsApi.remove(id);await load()},total=computed(()=>items.value.reduce((s,x)=>s+Number(x.currentEstimatedValue),0));onMounted(load)</script>
